import{r as d,j as e}from"./index-CfJUblmW.js";import{u as c}from"./useDialogA11y-BZVliQhD.js";const a={title:"POR QUE O SRL CANVAS?",contextAndGap:"Startups operam em contextos de alta incerteza. Por isso, um de seus maiores desafios não é apenas formular boas hipóteses, mas compreender o que já foi validado, o que ainda é suposição e onde estão os principais gargalos de maturidade do negócio. Frameworks como o Business Model Canvas (BMC) são úteis para estruturar hipóteses sobre proposta de valor, clientes, canais, receitas e operações, mas não foram desenhados para medir o nível de validação dessas hipóteses. De modo semelhante, o Technology Readiness Level (TRL) foca na prontidão tecnológica, mas não aborda o maior risco de muitas startups: desenvolver algo que o mercado não deseja ou não valoriza.",purpose:"Nesse contexto, o SRL Canvas foi desenvolvido como uma ferramenta visual e prática que complementa o BMC. Enquanto o BMC organiza hipóteses sobre o modelo de negócio, o SRL Canvas permite diagnosticar, em 12 dimensões essenciais, o estágio de maturidade e validação dessas hipóteses.",whoShouldUseTitle:"1. Quem Deve Usar Este Guia",whoShouldUseIntro:"O SRL Canvas atende diferentes atores do ecossistema de inovação, sempre com foco em diagnóstico, aprendizado e tomada de decisão:",whoShouldUse:["Fundadores de startups: Apoiar a autoavaliação, identificar gargalos e orientar a priorização de testes e validações.","Aceleradoras e incubadoras: Diagnosticar e acompanhar startups de portfólio com maior consistência comparativa.","Investidores anjo e fundos: Apoiar análises de risco e due diligence, especialmente quando as pontuações são acompanhadas de evidências.","Pesquisadores e acadêmicos: Utilizar o framework como instrumento analítico em estudos sobre maturidade, validação e evolução de startups."],propositionTitle:"2. O que o SRL Canvas se Propõe a Ser",propositionItems:["Ferramenta diagnóstica: Avalia a maturidade da startup em níveis de 1 a 9, com base em critérios objetivos e evidências.","Bússola de aprendizado: Indica onde a startup precisa validar mais, aprender mais ou corrigir rotas.","Estrutura market-first: Parte do princípio de que a maturidade de mercado e cliente é um dos principais determinantes da evolução sustentável do negócio."],propositionSummary:"Em síntese, o SRL Canvas é uma ferramenta diagnóstica baseada em evidências. Por isso, recomenda-se que as pontuações atribuídas a cada bloco sejam sempre sustentadas por registros verificáveis, conforme o protocolo de evidências do guia oficial.",notTitle:"O que o SRL Canvas Não É",notDescription:"O SRL Canvas não substitui ferramentas de formulação estratégica, planejamento financeiro detalhado, modelagem societária ou estruturação jurídica. Ele funciona como um painel diagnóstico de maturidade e deve ser utilizado em conjunto com outras ferramentas de gestão, validação e execução."};function u({isOpen:o,onClose:t}){const{dialogRef:i,initialFocusRef:r}=c(o);return d.useEffect(()=>{if(!o)return;const s=n=>{n.key==="Escape"&&t()};return window.addEventListener("keydown",s),()=>window.removeEventListener("keydown",s)},[o,t]),o?e.jsx("div",{className:"fixed inset-0 z-40 flex items-end justify-center p-4 md:items-center",style:{background:"rgba(8,12,22,.5)",backdropFilter:"blur(3px)"},children:e.jsxs("div",{ref:i,tabIndex:-1,role:"dialog","aria-modal":"true","aria-label":"Sobre o SRL Canvas",className:"max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-modal bg-surface font-sans text-ink shadow-lg",children:[e.jsxs("div",{className:"flex items-center justify-between border-b border-stroke p-4",children:[e.jsx("h2",{className:"font-display text-lg font-bold text-ink",children:"Sobre o SRL Canvas"}),e.jsx("button",{ref:r,type:"button",className:"flex size-9 items-center justify-center rounded-lg text-ink-2 hover:bg-surface-2",onClick:t,"aria-label":"Fechar",children:e.jsx("span",{className:"material-symbols-outlined","aria-hidden":"true",children:"close"})})]}),e.jsxs("div",{className:"space-y-4 p-4 md:p-6",children:[e.jsx("h3",{className:"font-display text-base font-bold text-ink",children:a.title}),e.jsx("p",{className:"text-sm text-ink-2",children:a.contextAndGap}),e.jsx("p",{className:"text-sm text-ink-2",children:a.purpose}),e.jsxs("section",{className:"space-y-2",children:[e.jsx("h4",{className:"text-sm font-semibold text-ink",children:a.whoShouldUseTitle}),e.jsx("p",{className:"text-sm text-ink-2",children:a.whoShouldUseIntro}),e.jsx("ul",{className:"list-disc space-y-1 pl-5 text-sm text-ink-2",children:a.whoShouldUse.map(s=>e.jsx("li",{children:s},s))})]}),e.jsxs("section",{className:"space-y-2",children:[e.jsx("h4",{className:"text-sm font-semibold text-ink",children:a.propositionTitle}),e.jsx("ul",{className:"list-disc space-y-1 pl-5 text-sm text-ink-2",children:a.propositionItems.map(s=>e.jsx("li",{children:s},s))}),e.jsx("p",{className:"text-sm text-ink-2",children:a.propositionSummary})]}),e.jsxs("section",{className:"space-y-2 rounded-card border border-stroke bg-inset p-3",children:[e.jsx("h4",{className:"text-sm font-semibold text-ink",children:a.notTitle}),e.jsx("p",{className:"text-sm text-ink-2",children:a.notDescription})]})]}),e.jsx("div",{className:"flex justify-end border-t border-stroke p-4",children:e.jsx("button",{type:"button",className:"rounded-[10px] bg-brand px-4 py-2 text-sm font-semibold text-brand-fg transition hover:brightness-110",onClick:t,children:"Fechar"})})]})}):null}export{u as A};
